def strategy(history, rng):
    if not history:
        return 'C'

    n = len(history)
    my_last, opp_last = history[-1]

    # Count how often opponent has defected in recent history
    recent = history[-10:]
    opp_defects_recent = sum(1 for _, o in recent if o == 'D')

    # Count total defections by opponent
    opp_defects_total = sum(1 for _, o in history if o == 'D')

    # Count my defections
    my_defects_total = sum(1 for m, _ in history if m == 'D')

    # If opponent has never defected, cooperate
    if opp_defects_total == 0:
        # But occasionally test if we're far in to see if they're exploitable
        if n > 50 and n < 60 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # Defection ratio of opponent
    opp_ratio = opp_defects_total / n

    # Retaliate immediately if opponent just defected while we cooperated
    if opp_last == 'D' and my_last == 'C':
        # Tit-for-tat-like: defect back unless opponent seems mostly cooperative
        if opp_defects_recent <= 1 and n > 5:
            return 'C'
        return 'D'

    # If opponent defected last turn, defect with high probability
    if opp_last == 'D':
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Opponent cooperated last turn
    # Be forgiving but not too forgiving
    if opp_ratio > 0.4:
        # Opponent is quite defective - be cautious
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    # Mostly cooperative opponent
    # Consider occasional probing if we've been too cooperative
    if my_defects_total == 0 and n > 20:
        if rng.random() < 0.08:
            return 'D'

    # Near end of match: if opponent has been mostly cooperative, stay cooperative
    if n >= 95:
        if opp_ratio < 0.2:
            return 'C'
        # If opponent is exploitative, defect
        if opp_ratio > 0.5:
            return 'D'
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Standard: cooperate if opponent mostly cooperates
    if opp_defects_recent == 0:
        return 'C'

    # If recent defections are moderate, mix
    if opp_defects_recent <= 2:
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    # More than 2 recent defections - defect more
    if rng.random() < 0.6:
        return 'D'
    return 'C'

